insert into public.profiles (id, user_id, nome, peso_kg, altura_cm, sexo, nivel_atividade, objetivo, meta_treinos_semana, equipment, avoid_exercises, session_length_min, preferred_time, check_in_mode, peso_inicial_kg, peso_meta_kg, meta_iniciada_em, meta_prazo) values ('p1', 'demo', 'Marcelo Alves', 82.5, 178, 'masculino', 'moderado', 'manutencao', 4, array['Barbell', 'Dumbbells', 'Machine', 'Cable']::text[], '[]'::jsonb, 60, 'evening', 'card', 79.5, 88, '2026-04-26', '2026-11-30') on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e1', null, 'Bench Press', 'Chest', array['Triceps', 'Shoulders']::text[], 'Barbell', 'Lie on the bench with feet flat on the floor and grip the bar at shoulder width. Lower with control to the mid-chest. Press back up without locking your elbows.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e2', null, 'Incline Dumbbell Press', 'Chest', array['Shoulders', 'Triceps']::text[], 'Dumbbells', 'Set the bench between 30 and 45 degrees and hold the dumbbells at chest height. Lower until you feel a stretch in the upper chest. Press up, lightly bringing the dumbbells together at the top.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e3', null, 'Decline Bench Press', 'Chest', array['Triceps']::text[], 'Barbell', 'Set the bench to decline and secure your legs. Lower the bar toward the lower chest. Press back up keeping your wrists aligned.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e4', null, 'Pec Deck Machine', 'Chest', array['Shoulders']::text[], 'Machine', 'Sit with your back supported and hold the handles at chest height. Bring your arms together in a slow arc, squeezing the chest. Return under control, feeling the stretch.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e5', null, 'Cable Crossover', 'Chest', array['Shoulders']::text[], 'Cable', 'Stand in the center of the cable with one foot slightly forward. Bring your hands forward and down, crossing them slightly. Return slowly without letting your shoulders rise.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e6', null, 'Push-up', 'Chest', array['Triceps', 'Core']::text[], 'Bodyweight', 'Place your hands slightly wider than shoulder width and keep your body straight. Lower until your chest almost touches the floor. Press back up while keeping your core tight.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e7', null, 'Barbell Squat', 'Quads', array['Glutes', 'Core', 'Hamstrings']::text[], 'Barbell', 'Rest the bar on your upper back, feet shoulder-width apart, chest up. Lower by pushing your hips back until your thighs break parallel. Press up through the middle of your foot.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e8', null, 'Front Squat', 'Quads', array['Glutes', 'Core']::text[], 'Barbell', 'Hold the bar on the front delts with elbows high. Lower while keeping your torso as upright as possible. Drive up without letting your elbows drop.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e9', null, 'Leg Press', 'Quads', array['Glutes']::text[], 'Machine', 'Place your feet on the platform shoulder-width apart and release the safety. Lower until your knees reach about 90 degrees. Press without fully locking your knees.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e10', null, 'Leg Extension', 'Quads', '{}'::text[], 'Machine', 'Adjust the seat so your knee aligns with the machine axis. Extend your legs until just short of lockout, squeezing the quads. Lower under control for two seconds.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e11', null, 'Dumbbell Lunge', 'Quads', array['Glutes', 'Hamstrings']::text[], 'Dumbbells', 'Hold a dumbbell in each hand and step forward. Lower until your back knee nearly touches the floor. Push back up through the front leg.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e12', null, 'Bulgarian Split Squat', 'Quads', array['Glutes']::text[], 'Dumbbells', 'Rest your back foot on a bench and keep your torso slightly leaned forward. Lower until you feel the glute stretch. Rise through the front leg without bouncing.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e13', null, 'Hack Squat', 'Quads', array['Glutes']::text[], 'Machine', 'Set your shoulders on the pads and keep your back supported. Lower your hips under control. Press through the middle of your foot.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e14', null, 'Deadlift', 'Hamstrings', array['Glutes', 'Lower back', 'Traps']::text[], 'Barbell', 'With the bar over mid-foot, grip with a neutral spine and chest up. Lift by pushing the floor away and extending hips and knees together. Lower keeping the bar close to your legs.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e15', null, 'Romanian Deadlift', 'Hamstrings', array['Glutes', 'Lower back']::text[], 'Barbell', 'Hold the bar in front with knees slightly bent. Push your hips back, lowering the bar along your legs. Rise by contracting glutes and hamstrings.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e16', null, 'Lying Leg Curl', 'Hamstrings', array['Calves']::text[], 'Machine', 'Lie face down with the pad above the Achilles. Curl your heels toward your glutes. Lower slowly without dropping the weight.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e17', null, 'Seated Leg Curl', 'Hamstrings', '{}'::text[], 'Machine', 'Sit with your back supported and the pad over your lower calf. Curl your feet down and back, squeezing the hamstrings. Return under control.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e18', null, 'Hip Thrust', 'Glutes', array['Hamstrings', 'Core']::text[], 'Barbell', 'Rest your upper back on a bench with the bar over your hips. Thrust your hips up until your torso and thighs align. Squeeze your glutes for one second at the top.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e19', null, 'Hip Abduction Machine', 'Glutes', '{}'::text[], 'Machine', 'Sit with the pads on the outside of your thighs. Open your legs to a comfortable range. Return while resisting the weight.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e20', null, 'Standing Calf Raise', 'Calves', '{}'::text[], 'Machine', 'Place the balls of your feet on the platform with knees extended. Rise onto your toes as high as possible. Lower until you feel a full stretch.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e21', null, 'Seated Calf Raise', 'Calves', '{}'::text[], 'Machine', 'Sit with the pad over your knees and the balls of your feet on the platform. Raise your heels as high as possible. Lower slowly, controlling the stretch.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e22', null, 'Barbell Row', 'Back', array['Biceps', 'Lower back']::text[], 'Barbell', 'Lean your torso to about 45 degrees with a neutral spine. Pull the bar toward your lower chest, retracting your shoulder blades. Lower without raising your torso.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e23', null, 'One-Arm Dumbbell Row', 'Back', array['Biceps']::text[], 'Dumbbells', 'Support one hand on the bench and keep your back flat. Pull the dumbbell to the side of your torso. Lower with a full lat stretch.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e24', null, 'Lat Pulldown', 'Back', array['Biceps']::text[], 'Cable', 'Grip the bar wide with your thighs locked under the pad. Pull until the bar reaches your upper chest. Return under control without shrugging.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e25', null, 'Seated Cable Row', 'Back', array['Biceps']::text[], 'Cable', 'Sit with your feet braced and torso slightly leaned forward. Pull the triangle to your lower abs, retracting your shoulder blades. Return with a full lat stretch.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e26', null, 'Chest-Supported Row', 'Back', array['Biceps', 'Traps']::text[], 'Machine', 'Rest your chest on the support and grip the handles. Pull with your elbows going back. Lower slowly.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e27', null, 'Pull-up', 'Back', array['Biceps', 'Core']::text[], 'Bodyweight', 'Grip the bar pronated at shoulder width. Pull until your chin clears the bar. Lower with control all the way down.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e28', null, 'Rope Pulldown', 'Back', array['Shoulders']::text[], 'Cable', 'Standing, hold the rope with arms extended overhead. Pull down keeping your arms straight. Return under control.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e29', null, 'Overhead Press', 'Shoulders', array['Triceps', 'Core']::text[], 'Barbell', 'Standing, hold the bar at collar height with your core tight. Press overhead until your arms extend. Lower with control to chin height.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e30', null, 'Dumbbell Shoulder Press', 'Shoulders', array['Triceps']::text[], 'Dumbbells', 'Sit with your back supported and dumbbells at ear height. Press up without banging the dumbbells. Lower to 90 degrees under control.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e31', null, 'Lateral Raise', 'Shoulders', '{}'::text[], 'Dumbbells', 'Stand with dumbbells at your sides and elbows slightly bent. Raise to shoulder height, leading with your elbows. Lower in two seconds.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e32', null, 'Front Raise', 'Shoulders', '{}'::text[], 'Dumbbells', 'Hold the dumbbells in front of your thighs. Raise your arms to eye level. Lower under control without swinging.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e33', null, 'Reverse Pec Deck', 'Shoulders', array['Back']::text[], 'Machine', 'Sit facing the machine with your chest supported. Open your arms back, squeezing the rear shoulders. Return slowly.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e34', null, 'Dumbbell Shrug', 'Traps', array['Shoulders']::text[], 'Dumbbells', 'Hold dumbbells at your sides with arms extended. Shrug your shoulders toward your ears. Lower with a full trap stretch.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e35', null, 'Barbell Curl', 'Biceps', array['Forearms']::text[], 'Barbell', 'Standing, grip the bar supinated at shoulder width. Curl without moving your shoulders. Lower until your arms are fully extended.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e36', null, 'Alternating Dumbbell Curl', 'Biceps', array['Forearms']::text[], 'Dumbbells', 'Standing with dumbbells at your sides. Curl one arm, rotating the wrist outward. Lower under control and alternate.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e37', null, 'Hammer Curl', 'Biceps', array['Forearms']::text[], 'Dumbbells', 'Hold the dumbbells with a neutral grip. Curl keeping your wrists fixed. Lower slowly.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e38', null, 'Skull Crusher', 'Triceps', '{}'::text[], 'Barbell', 'Lie on the bench with the bar above your forehead and elbows pointing at the ceiling. Lower the bar near your head by bending your elbows. Extend without flaring your elbows.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e39', null, 'Tricep Rope Pushdown', 'Triceps', '{}'::text[], 'Cable', 'Stand with elbows pinned to your sides and hold the rope. Extend your elbows, spreading the rope at the bottom. Return to 90 degrees under control.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e40', null, 'Overhead Tricep Extension', 'Triceps', '{}'::text[], 'Dumbbells', 'Sit and hold a dumbbell with both hands above your head. Lower behind your head by bending your elbows. Extend without flaring your elbows.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e41', null, 'Bench Dip', 'Triceps', array['Chest']::text[], 'Bodyweight', 'Place your hands on the edge of the bench with your legs extended in front. Lower your hips by bending your elbows. Press until your arms extend.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e42', null, 'Plank', 'Core', array['Shoulders']::text[], 'Bodyweight', 'Support your forearms and toes while keeping your body aligned. Brace your abs and glutes. Breathe while holding the position.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e43', null, 'Cable Crunch', 'Core', '{}'::text[], 'Cable', 'Kneel facing away from the cable, holding the rope by your head. Crunch your torso, bringing your ribs toward your hips. Return slowly.', false) on conflict (id) do nothing;
